// ============ MAP INIT ============
const map = L.map('map', {
  zoomControl: true,
  attributionControl: true,
  minZoom: 3,
  maxZoom: 9,
  worldCopyJump: false,
  maxBoundsViscosity: 0.6
}).setView([2.5, 112], 5);

// Bounds padded generously beyond the region of interest so the map always has
// room to pan, even at minZoom on odd aspect ratios (a tight maxBounds box can
// otherwise fully lock dragging if it matches the viewport exactly).
map.setMaxBounds([[-45, 55], [50, 180]]);

// Explicitly ensure dragging/touch gestures are enabled (defensive — some
// container layout timing issues can otherwise leave Leaflet's handlers
// in an inconsistent state on first paint).
map.dragging.enable();
map.touchZoom.enable();
map.doubleClickZoom.enable();
map.scrollWheelZoom.enable();

// Recalculate the map's internal size shortly after load, in case fonts/layout
// were still shifting when Leaflet first measured its container.
window.addEventListener('load', () => {
  setTimeout(() => map.invalidateSize(), 200);
});

// ============ FULLSCREEN CONTROL ============
// Expands just the map panel (.map-wrap) to fill the viewport via the
// standard Fullscreen API, rather than the whole app — the map is the
// thing that benefits from the extra room, and this keeps tabs/legend
// state untouched underneath. Sits directly under the zoom control.
const FullscreenControl = L.Control.extend({
  options: { position: 'topleft' },
  onAdd: function(){
    const container = L.DomUtil.create('div', 'leaflet-bar leaflet-control leaflet-control-fullscreen');
    const link = L.DomUtil.create('a', '', container);
    link.href = '#';
    link.title = 'Toggle fullscreen';
    link.setAttribute('role', 'button');
    link.setAttribute('aria-label', 'Toggle fullscreen map');
    link.innerHTML = '&#x26F6;'; // ⛶

    const mapWrapEl = document.querySelector('.map-wrap');

    function isFullscreen(){
      return document.fullscreenElement === mapWrapEl;
    }

    function updateIcon(){
      link.innerHTML = isFullscreen() ? '&#x2715;' : '&#x26F6;'; // ✕ when open, ⛶ when closed
      link.title = isFullscreen() ? 'Exit fullscreen' : 'Toggle fullscreen';
    }

    L.DomEvent.on(link, 'click', function(e){
      L.DomEvent.stopPropagation(e);
      L.DomEvent.preventDefault(e);
      if (!isFullscreen()){
        if (mapWrapEl.requestFullscreen){
          mapWrapEl.requestFullscreen().catch(() => {});
        }
      } else {
        if (document.exitFullscreen){
          document.exitFullscreen().catch(() => {});
        }
      }
    });

    // Prevent the map from panning/zooming when interacting with the control
    L.DomEvent.disableClickPropagation(container);
    L.DomEvent.disableScrollPropagation(container);

    document.addEventListener('fullscreenchange', () => {
      updateIcon();
      // Leaflet needs a size recalculation on every fullscreen transition
      setTimeout(() => map.invalidateSize(), 100);
    });

    return container;
  }
});
map.addControl(new FullscreenControl());

// Parchment-toned sea background via CSS on tile pane; no raster tiles (embedded vector coastlines only)
map.getPane('mapPane').style.background = '#5C7E8C';

// aged paper filter overlay for entire map container (subtle)
document.getElementById('map').style.filter = 'saturate(0.9) contrast(1.02)';

L.control.attribution({prefix: false}).addAttribution('Coastlines: Natural Earth (public domain) · Stylized, not surveyed for accuracy');

// ============ COASTLINE LAYER ============
function landStyle(feature){
  return {
    fillColor: '#E8D9B5',
    fillOpacity: 0.95,
    color: '#2B2320',
    weight: 1.1,
    opacity: 0.85
  };
}

const coastlineLayer = L.geoJSON(coastlines, { style: landStyle }).addTo(map);

